using System.Text;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using Microsoft.OpenApi.Models;
using UserService.Data;
using UserService.Models;
using UserService.Services;

var builder = WebApplication.CreateBuilder(args);

// 1. Database Configuration (PostgreSQL - RescuePlateDB)
var connectionString = builder.Configuration.GetConnectionString("PostgreSQLConnection")
    ?? throw new InvalidOperationException(
        "PostgreSQLConnection connection string is not configured.");

builder.Services.AddDbContext<RescuePlateDbContext>(options =>
{
    options.UseNpgsql(connectionString);
});

// Standard ASP.NET Core Health Checks
builder.Services.AddHealthChecks()
    .AddDbContextCheck<RescuePlateDbContext>(
        name: "PostgreSQL",
        tags: new[] { "db", "data" });

// 2. Dependency Injection Services
builder.Services.AddMemoryCache();
builder.Services.AddHttpContextAccessor();
builder.Services.AddHttpClient("DonationService", client =>
{
    client.BaseAddress = new Uri(builder.Configuration["Services:DonationServiceUrl"] ?? "http://localhost:5001");
    client.Timeout = TimeSpan.FromSeconds(5);
});
builder.Services.AddHttpClient("RequestService", client =>
{
    client.BaseAddress = new Uri(builder.Configuration["Services:RequestServiceUrl"] ?? "http://localhost:5002");
    client.Timeout = TimeSpan.FromSeconds(5);
});
builder.Services.AddHttpClient("DeliveryService", client =>
{
    client.BaseAddress = new Uri(builder.Configuration["Services:DeliveryServiceUrl"] ?? "http://localhost:5003");
    client.Timeout = TimeSpan.FromSeconds(5);
});
builder.Services.AddScoped<ITokenService, TokenService>();
builder.Services.AddScoped<IAuthService, AuthService>();
builder.Services.AddScoped<IProfileService, ProfileService>();
builder.Services.AddScoped<IAdminService, AdminService>();
builder.Services.AddScoped<Microsoft.AspNetCore.Authorization.IAuthorizationHandler, VerifiedAdminRequirementHandler>();

// 3. JWT Authentication & Authorization
var secretKey = builder.Configuration["Jwt:SecretKey"] ?? "RescuePlate_Super_Secret_Key_For_Jwt_Authentication_2026_Sprint1_RescueFood";
var issuer = builder.Configuration["Jwt:Issuer"] ?? "RescuePlate.UserService";
var audience = builder.Configuration["Jwt:Audience"] ?? "RescuePlate.Client";
var frontendUrl = builder.Configuration["FrontendUrl"] ?? "http://localhost:5173";

builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.RequireHttpsMetadata = false;
        options.SaveToken = true;
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,
            ValidIssuer = issuer,
            ValidAudience = audience,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),
            ClockSkew = TimeSpan.Zero
        };
    });

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("DonorOnly", policy => policy.RequireRole("DONOR"));
    options.AddPolicy("OrganizationOnly", policy => policy.RequireRole("ORGANIZATION"));
    options.AddPolicy("AdminOnly", policy => policy.RequireRole("ADMIN"));
    options.AddPolicy("VerifiedAdminOnly", policy =>
    {
        policy.RequireRole("ADMIN");
        policy.Requirements.Add(new VerifiedAdminRequirement());
    });
});

// 4. CORS Policy for Frontend (http://localhost:5173)
builder.Services.AddCors(options =>
{
    options.AddPolicy("AllowFrontend", policy =>
    {
        policy.WithOrigins(frontendUrl, "http://localhost:3000")
              .AllowAnyHeader()
              .AllowAnyMethod()
              .AllowCredentials();
    });
});

builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        options.JsonSerializerOptions.Converters.Add(new System.Text.Json.Serialization.JsonStringEnumConverter());
    });
builder.Services.AddEndpointsApiExplorer();

// 5. Swagger Configuration with JWT Bearer Support
builder.Services.AddSwaggerGen(c =>
{
    c.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "RescuePlate User & Auth API",
        Version = "v1.0",
        Description = "Sprint 1 Microservice for Authentication, Roles, and User Profiles."
    });

    c.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
    {
        Description = "JWT Authorization header using the Bearer scheme. Example: \"Bearer {token}\"",
        Name = "Authorization",
        In = ParameterLocation.Header,
        Type = SecuritySchemeType.ApiKey,
        Scheme = "Bearer"
    });

    c.AddSecurityRequirement(new OpenApiSecurityRequirement
    {
        {
            new OpenApiSecurityScheme
            {
                Reference = new OpenApiReference
                {
                    Type = ReferenceType.SecurityScheme,
                    Id = "Bearer"
                }
            },
            Array.Empty<string>()
        }
    });
});

var app = builder.Build();

// 6. Automatic Database Initialization & Seeding
try
{
    var logger = app.Services.GetRequiredService<ILogger<Program>>();
    DbInitializer.Initialize(connectionString, app.Services, logger);
}
catch (Exception ex)
{
    var logger = app.Services.GetRequiredService<ILogger<Program>>();
    logger.LogWarning(ex, "Database auto-initialization exception. Ensure PostgreSQL service is running.");
}

// 7. Middleware Pipeline
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

var wwwRootPath = Path.Combine(app.Environment.ContentRootPath, "wwwroot");
if (!Directory.Exists(wwwRootPath))
{
    Directory.CreateDirectory(wwwRootPath);
}
var profilesPath = Path.Combine(wwwRootPath, "uploads", "profiles");
if (!Directory.Exists(profilesPath))
{
    Directory.CreateDirectory(profilesPath);
}

app.UseStaticFiles(new StaticFileOptions
{
    FileProvider = new Microsoft.Extensions.FileProviders.PhysicalFileProvider(wwwRootPath),
    RequestPath = ""
});
app.UseCors("AllowFrontend");
app.UseAuthentication();
app.UseAuthorization();

// Standard ASP.NET Core Health Checks Endpoint
app.MapHealthChecks("/health");

app.MapControllers();

app.Run();

using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Caching.Memory;
using UserService.Data;
using UserService.DTOs;
using UserService.Models;

namespace UserService.Services;

public interface IAdminService
{
    Task<(bool Success, string Message, AdminPreAuthResponseDto? Data)> AdminLoginAsync(LoginDto dto, string clientIp);
    Task<(bool Success, string Message, AuthResponseDto? Data)> VerifyAccessKeyAsync(VerifyAccessKeyDto dto, string clientIp);
    Task<(bool Success, string Message)> UpdateUserStatusAsync(Guid userId, bool isActive, Guid adminUserId, string adminEmail, string clientIp);
    Task<(bool Success, string Message, MonitoringOverviewDto? Data)> GetMonitoringOverviewAsync(string clientIp);
    Task<(bool Success, string Message, List<ActivityLogDto> Data)> GetActivityLogsAsync(int page = 1, int pageSize = 50);
}

public class AdminService : IAdminService
{
    private readonly RescuePlateDbContext _db;
    private readonly ITokenService _tokenService;
    private readonly IConfiguration _config;
    private readonly IMemoryCache _cache;
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly ILogger<AdminService> _logger;

    public AdminService(
        RescuePlateDbContext db,
        ITokenService tokenService,
        IConfiguration config,
        IMemoryCache cache,
        IHttpClientFactory httpClientFactory,
        IHttpContextAccessor httpContextAccessor,
        ILogger<AdminService> logger)
    {
        _db = db;
        _tokenService = tokenService;
        _config = config;
        _cache = cache;
        _httpClientFactory = httpClientFactory;
        _httpContextAccessor = httpContextAccessor;
        _logger = logger;
    }

    public async Task<(bool Success, string Message, AdminPreAuthResponseDto? Data)> AdminLoginAsync(LoginDto dto, string clientIp)
    {
        var normalizedEmail = dto.Email.Trim().ToLowerInvariant();

        var user = await _db.Users
            .FirstOrDefaultAsync(u => u.Email.ToLower() == normalizedEmail);

        if (user == null)
        {
            await LogActivityAsync("ADMIN_LOGIN_FAILED", null, normalizedEmail, null, clientIp, "Attempted login with non-existent email.");
            return (false, "Invalid administrator credentials.", null);
        }

        // Check Password
        bool isPasswordValid = BCrypt.Net.BCrypt.Verify(dto.Password, user.PasswordHash);
        if (!isPasswordValid)
        {
            await LogActivityAsync("ADMIN_LOGIN_FAILED", user.Id, user.Email, null, clientIp, "Invalid password provided.");
            return (false, "Invalid administrator credentials.", null);
        }

        // Check Role Claim (Scenario 4)
        if (user.Role != UserRole.ADMIN)
        {
            await LogActivityAsync("ADMIN_LOGIN_FAILED", user.Id, user.Email, null, clientIp, $"User with role '{user.Role}' attempted admin login.");
            return (false, "Access denied: Account is not an administrator.", null);
        }

        // Check Active Account Status (Scenario 3)
        if (!user.IsActive)
        {
            await LogActivityAsync("ADMIN_LOGIN_FAILED", user.Id, user.Email, null, clientIp, "Inactive admin account attempted login.");
            return (false, "Administrator account is inactive.", null);
        }

        // Issue short-lived Pre-Auth Challenge Token (5 min expiry)
        int challengeExpiryMinutes = int.TryParse(_config["AdminSettings:ChallengeTokenExpiryMinutes"], out var exp) ? exp : 5;
        var challengeToken = _tokenService.GeneratePreAuthChallengeToken(user, challengeExpiryMinutes);

        await LogActivityAsync("ADMIN_LOGIN_SUCCESS", user.Id, user.Email, null, clientIp, "Step 1 admin credential authentication succeeded.");

        var responseData = new AdminPreAuthResponseDto
        {
            Email = user.Email,
            ChallengeToken = challengeToken,
            RequiresAccessKey = true,
            ExpiresInSeconds = challengeExpiryMinutes * 60
        };

        return (true, "Administrator credentials verified. Access Key required.", responseData);
    }

    public async Task<(bool Success, string Message, AuthResponseDto? Data)> VerifyAccessKeyAsync(VerifyAccessKeyDto dto, string clientIp)
    {
        // 1. Validate Challenge Token
        var principal = _tokenService.ValidateChallengeToken(dto.ChallengeToken);
        if (principal == null)
        {
            return (false, "Invalid or expired pre-authentication challenge. Please sign in again.", null);
        }

        var userIdStr = principal.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
        if (string.IsNullOrEmpty(userIdStr) || !Guid.TryParse(userIdStr, out var userId))
        {
            return (false, "Invalid challenge payload.", null);
        }

        var user = await _db.Users
            .Include(u => u.DonorProfile)
            .Include(u => u.OrganizationProfile)
            .FirstOrDefaultAsync(u => u.Id == userId);

        if (user == null || user.Role != UserRole.ADMIN)
        {
            await LogActivityAsync("ACCESS_KEY_FAILED", userId, principal.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value ?? "Unknown", null, clientIp, "Non-admin attempted access key verification.");
            return (false, "Administrator access verification denied.", null);
        }

        if (!user.IsActive)
        {
            await LogActivityAsync("ACCESS_KEY_FAILED", user.Id, user.Email, null, clientIp, "Inactive admin account attempted access key verification.");
            return (false, "Administrator account is inactive.", null);
        }

        // 2. Global Rate-Limiting Across Account & IP
        string emailCacheKey = $"RateLimit_AdminAccessKey_{user.Email.ToLower()}";
        string ipCacheKey = $"RateLimit_AdminAccessKey_IP_{clientIp}";

        int failedEmailCount = _cache.Get<int?>(emailCacheKey) ?? 0;
        int failedIpCount = _cache.Get<int?>(ipCacheKey) ?? 0;

        int maxAllowedAttempts = int.TryParse(_config["AdminSettings:MaxFailedAttempts"], out var maxAtt) ? maxAtt : 5;
        int lockoutMinutes = int.TryParse(_config["AdminSettings:LockoutMinutes"], out var lockMin) ? lockMin : 15;

        if (failedEmailCount >= maxAllowedAttempts || failedIpCount >= maxAllowedAttempts)
        {
            await LogActivityAsync("ACCESS_KEY_LOCKOUT", user.Id, user.Email, null, clientIp, $"Access Key verification locked out due to {maxAllowedAttempts} failed attempts.");
            return (false, $"Too many failed access key attempts. Account locked out for {lockoutMinutes} minutes.", null);
        }

        // 3. Verify Access Key
        string expectedAccessKey = _config["AdminSettings:AccessKey"] ?? "ADMIN-SECURE-KEY-2026";
        if (dto.AccessKey != expectedAccessKey)
        {
            // Increment failed attempt counters
            _cache.Set(emailCacheKey, failedEmailCount + 1, TimeSpan.FromMinutes(lockoutMinutes));
            _cache.Set(ipCacheKey, failedIpCount + 1, TimeSpan.FromMinutes(lockoutMinutes));

            await LogActivityAsync("ACCESS_KEY_FAILED", user.Id, user.Email, null, clientIp, $"Incorrect access key attempt ({failedEmailCount + 1}/{maxAllowedAttempts}).");
            return (false, "Invalid Administrator Access Key.", null);
        }

        // 4. Verification Successful -> Clear lockout counter & log success
        _cache.Remove(emailCacheKey);
        _cache.Remove(ipCacheKey);

        await LogActivityAsync("ACCESS_KEY_SUCCESS", user.Id, user.Email, null, clientIp, "Administrator access key verified successfully.");

        // Generate final Verified Admin Token
        var token = _tokenService.GenerateVerifiedAdminToken(user, "RescuePlate System Admin", "System Administrator");

        var responseData = new AuthResponseDto
        {
            UserId = user.Id,
            Email = user.Email,
            Role = user.Role.ToString(),
            Name = "System Administrator",
            BusinessName = "RescuePlate System Admin",
            Token = token,
            ExpiresAt = DateTime.UtcNow.AddDays(7)
        };

        return (true, "Administrator access verified successfully!", responseData);
    }

    public async Task<(bool Success, string Message)> UpdateUserStatusAsync(Guid userId, bool isActive, Guid adminUserId, string adminEmail, string clientIp)
    {
        var user = await _db.Users.FindAsync(userId);
        if (user == null)
        {
            return (false, "User not found.");
        }

        // Prevent status modification for administrator accounts
        if (user.Role == UserRole.ADMIN)
        {
            return (false, "Administrator account status cannot be modified.");
        }

        user.IsActive = isActive;
        user.UpdatedAt = DateTime.UtcNow;
        await _db.SaveChangesAsync();

        string action = isActive ? "USER_REACTIVATED" : "USER_DEACTIVATED";
        string details = $"User account '{user.Email}' status updated to {(isActive ? "ACTIVE" : "INACTIVE")}.";
        await LogActivityAsync(action, adminUserId, adminEmail, user.Id, clientIp, details);

        return (true, $"User account has been {(isActive ? "activated" : "deactivated")}.");
    }

    public async Task<(bool Success, string Message, MonitoringOverviewDto? Data)> GetMonitoringOverviewAsync(string clientIp)
    {
        var totalUsers = await _db.Users.CountAsync();
        var activeDonors = await _db.Users.CountAsync(u => u.Role == UserRole.DONOR && u.IsActive);
        var activeOrgs = await _db.Users.CountAsync(u => u.Role == UserRole.ORGANIZATION && u.IsActive);

        var recentLogs = await _db.AdminActivityLogs
            .OrderByDescending(l => l.Timestamp)
            .Take(15)
            .Select(l => new ActivityLogDto
            {
                Id = l.Id,
                Action = l.Action,
                PerformedByEmail = l.PerformedByEmail,
                ClientIp = l.ClientIp,
                Details = l.Details,
                Timestamp = l.Timestamp
            })
            .ToListAsync();

        string? authHeader = _httpContextAccessor.HttpContext?.Request.Headers["Authorization"].ToString();

        object? donationData = null;
        try
        {
            var donationClient = _httpClientFactory.CreateClient("DonationService");
            if (!string.IsNullOrEmpty(authHeader))
            {
                donationClient.DefaultRequestHeaders.TryAddWithoutValidation("Authorization", authHeader);
            }
            var response = await donationClient.GetAsync("/api/donations/admin/summary");
            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadFromJsonAsync<JsonElement>();
                donationData = json;
            }
            else
            {
                donationData = new { status = "UNAVAILABLE", statusCode = (int)response.StatusCode };
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Could not fetch donation statistics from DonationService");
            donationData = new { status = "UNAVAILABLE", error = ex.Message };
        }

        object? requestData = null;
        try
        {
            var requestClient = _httpClientFactory.CreateClient("RequestService");
            if (!string.IsNullOrEmpty(authHeader))
            {
                requestClient.DefaultRequestHeaders.TryAddWithoutValidation("Authorization", authHeader);
            }
            var response = await requestClient.GetAsync("/api/requests/admin/summary");
            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadFromJsonAsync<JsonElement>();
                requestData = json;
            }
            else
            {
                requestData = new { status = "UNAVAILABLE", statusCode = (int)response.StatusCode };
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Could not fetch request statistics from RequestService");
            requestData = new { status = "UNAVAILABLE", error = ex.Message };
        }

        object? deliveryData = null;
        try
        {
            var deliveryClient = _httpClientFactory.CreateClient("DeliveryService");
            if (!string.IsNullOrEmpty(authHeader))
            {
                deliveryClient.DefaultRequestHeaders.TryAddWithoutValidation("Authorization", authHeader);
            }
            var response = await deliveryClient.GetAsync("/api/deliveries/admin/summary");
            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadFromJsonAsync<JsonElement>();
                deliveryData = json;
            }
            else
            {
                deliveryData = new { status = "UNAVAILABLE", statusCode = (int)response.StatusCode };
            }
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Could not fetch delivery statistics from DeliveryWorkflowService");
            deliveryData = new { status = "UNAVAILABLE", error = ex.Message };
        }

        var overview = new MonitoringOverviewDto
        {
            TotalUsers = totalUsers,
            ActiveDonors = activeDonors,
            ActiveOrganizations = activeOrgs,
            DonationSummary = donationData,
            RequestSummary = requestData,
            DeliverySummary = deliveryData,
            RecentActivities = recentLogs
        };

        return (true, "Platform monitoring overview retrieved successfully.", overview);
    }

    public async Task<(bool Success, string Message, List<ActivityLogDto> Data)> GetActivityLogsAsync(int page = 1, int pageSize = 50)
    {
        var logs = await _db.AdminActivityLogs
            .OrderByDescending(l => l.Timestamp)
            .Skip((page - 1) * pageSize)
            .Take(pageSize)
            .Select(l => new ActivityLogDto
            {
                Id = l.Id,
                Action = l.Action,
                PerformedByEmail = l.PerformedByEmail,
                ClientIp = l.ClientIp,
                Details = l.Details,
                Timestamp = l.Timestamp
            })
            .ToListAsync();

        return (true, "Activity logs retrieved successfully.", logs);
    }

    private async Task LogActivityAsync(string action, Guid? performedByUserId, string performedByEmail, Guid? targetUserId, string clientIp, string details)
    {
        try
        {
            var log = new AdminActivityLog
            {
                Id = Guid.NewGuid(),
                Action = action,
                PerformedByUserId = performedByUserId,
                PerformedByEmail = performedByEmail,
                TargetUserId = targetUserId,
                ClientIp = clientIp,
                Details = details,
                Timestamp = DateTime.UtcNow
            };

            _db.AdminActivityLogs.Add(log);
            await _db.SaveChangesAsync();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to write AdminActivityLog to database.");
        }
    }
}

using Microsoft.EntityFrameworkCore;
using UserService.Data;
using UserService.DTOs;
using UserService.Models;

namespace UserService.Services;

public interface IAuthService
{
    Task<(bool Success, string Message, AuthResponseDto? Data)> RegisterAsync(RegisterDto dto);
    Task<(bool Success, string Message, AuthResponseDto? Data)> LoginAsync(LoginDto dto);
    Task<(bool Success, string Message)> ChangePasswordAsync(Guid userId, ChangePasswordDto dto);
    Task<(bool Success, string Message)> DeleteAccountAsync(Guid userId, string password);
}

public class AuthService : IAuthService
{
    private readonly RescuePlateDbContext _db;
    private readonly ITokenService _tokenService;

    public AuthService(RescuePlateDbContext db, ITokenService tokenService)
    {
        _db = db;
        _tokenService = tokenService;
    }

    public async Task<(bool Success, string Message, AuthResponseDto? Data)> RegisterAsync(RegisterDto dto)
    {
        // 0. Public Registration Guard - Rejects ADMIN role creation
        if (dto.Role == UserRole.ADMIN)
        {
            return (false, "Cannot register as Administrator via public registration.", null);
        }

        // 1. Unique Email Validation (SRS Acceptance Criteria)
        var normalizedEmail = dto.Email.Trim().ToLowerInvariant();
        var emailExists = await _db.Users.AnyAsync(u => u.Email.ToLower() == normalizedEmail);
        if (emailExists)
        {
            return (false, "An account with this email address already exists. Please sign in or use a different email.", null);
        }

        // 2. Secure Password Storage (SRS NFR3)
        var passwordHash = BCrypt.Net.BCrypt.HashPassword(dto.Password, workFactor: 11);

        // 3. Create User Entity
        var user = new User
        {
            Id = Guid.NewGuid(),
            Email = normalizedEmail,
            PasswordHash = passwordHash,
            Role = dto.Role,
            IsActive = true,
            CreatedAt = DateTime.UtcNow,
            UpdatedAt = DateTime.UtcNow
        };

        _db.Users.Add(user);

        // 4. Create Role-specific Profile (Sprint 1 Stories)
        string businessName = dto.BusinessOrOrgName.Trim();
        string contactName = string.IsNullOrWhiteSpace(dto.ContactName) ? businessName : dto.ContactName.Trim();

        if (dto.Role == UserRole.DONOR)
        {
            var donorProfile = new DonorProfile
            {
                Id = Guid.NewGuid(),
                UserId = user.Id,
                BusinessName = businessName,
                ContactPerson = contactName,
                DonorType = string.IsNullOrWhiteSpace(dto.DonorType) ? "Restaurant" : dto.DonorType,
                Address = dto.Location.Trim(),
                Phone = dto.Phone?.Trim() ?? string.Empty,
                CreatedAt = DateTime.UtcNow,
                UpdatedAt = DateTime.UtcNow
            };
            _db.DonorProfiles.Add(donorProfile);
        }
        else if (dto.Role == UserRole.ORGANIZATION)
        {
            var acceptedTypes = dto.AcceptedFoodTypes != null && dto.AcceptedFoodTypes.Count > 0
                ? string.Join(";", dto.AcceptedFoodTypes)
                : "Cooked Meals;Bakery";

            var orgProfile = new OrganizationProfile
            {
                Id = Guid.NewGuid(),
                UserId = user.Id,
                OrganizationName = businessName,
                ContactPerson = contactName,
                Address = dto.Location.Trim(),
                Phone = dto.Phone?.Trim() ?? string.Empty,
                AcceptedFoodCategories = acceptedTypes,
                CreatedAt = DateTime.UtcNow,
                UpdatedAt = DateTime.UtcNow
            };
            _db.OrganizationProfiles.Add(orgProfile);
        }

        await _db.SaveChangesAsync();

        // 5. Generate JWT Token
        var token = _tokenService.GenerateToken(user, businessName, contactName);

        var responseData = new AuthResponseDto
        {
            UserId = user.Id,
            Email = user.Email,
            Role = user.Role.ToString(),
            Name = contactName,
            BusinessName = businessName,
            Token = token,
            ExpiresAt = DateTime.UtcNow.AddDays(7)
        };

        return (true, "Registration successful!", responseData);
    }

    public async Task<(bool Success, string Message, AuthResponseDto? Data)> LoginAsync(LoginDto dto)
    {
        var normalizedEmail = dto.Email.Trim().ToLowerInvariant();

        var user = await _db.Users
            .Include(u => u.DonorProfile)
            .Include(u => u.OrganizationProfile)
            .FirstOrDefaultAsync(u => u.Email.ToLower() == normalizedEmail);

        if (user == null)
        {
            return (false, "Invalid email address or password.", null);
        }

        // Verify password hash
        bool isPasswordValid = BCrypt.Net.BCrypt.Verify(dto.Password, user.PasswordHash);
        if (!isPasswordValid)
        {
            return (false, "Invalid email address or password.", null);
        }

        // Check account activation (SRS FR4 & NFR4)
        if (!user.IsActive)
        {
            return (false, "Your account has been deactivated by the system administrator.", null);
        }

        // Prevent Administrator accounts from using standard user login (Fix 3)
        if (user.Role == UserRole.ADMIN)
        {
            return (false, "Administrator accounts must authenticate via the Administrator Portal at /admin/login.", null);
        }

        string businessName = user.Role switch
        {
            UserRole.DONOR => user.DonorProfile?.BusinessName ?? "Donor Business",
            UserRole.ORGANIZATION => user.OrganizationProfile?.OrganizationName ?? "Charity Organization",
            _ => "RescuePlate Admin"
        };

        string contactName = user.Role switch
        {
            UserRole.DONOR => user.DonorProfile?.ContactPerson ?? businessName,
            UserRole.ORGANIZATION => user.OrganizationProfile?.ContactPerson ?? businessName,
            _ => "Administrator"
        };

        var token = _tokenService.GenerateToken(user, businessName, contactName);

        var responseData = new AuthResponseDto
        {
            UserId = user.Id,
            Email = user.Email,
            Role = user.Role.ToString(),
            Name = contactName,
            BusinessName = businessName,
            ProfilePictureUrl = user.ProfilePictureUrl,
            Token = token,
            ExpiresAt = DateTime.UtcNow.AddDays(7)
        };

        return (true, "Signed in successfully!", responseData);
    }

    public async Task<(bool Success, string Message)> ChangePasswordAsync(Guid userId, ChangePasswordDto dto)
    {
        var user = await _db.Users.FindAsync(userId);
        if (user == null)
        {
            return (false, "User account not found.");
        }

        // 1. Verify current password (SRS AC Scenario 2)
        bool isCurrentPasswordValid = BCrypt.Net.BCrypt.Verify(dto.CurrentPassword, user.PasswordHash);
        if (!isCurrentPasswordValid)
        {
            return (false, "The current password you provided is incorrect.");
        }

        // 2. Validate confirmation match (SRS AC Scenario 4)
        if (dto.NewPassword != dto.ConfirmPassword)
        {
            return (false, "New password and confirmation password do not match.");
        }

        // 3. Prevent identical old password reuse
        if (BCrypt.Net.BCrypt.Verify(dto.NewPassword, user.PasswordHash))
        {
            return (false, "New password cannot be the same as your current password.");
        }

        // 4. Secure Password Storage with BCrypt work factor 11 (SRS AC Scenario 7)
        user.PasswordHash = BCrypt.Net.BCrypt.HashPassword(dto.NewPassword, workFactor: 11);
        user.UpdatedAt = DateTime.UtcNow;

        await _db.SaveChangesAsync();

        return (true, "Password has been changed successfully.");
    }

    public async Task<(bool Success, string Message)> DeleteAccountAsync(Guid userId, string password)
    {
        var user = await _db.Users.FindAsync(userId);
        if (user == null)
        {
            return (false, "User account not found.");
        }

        if (user.Role == UserRole.ADMIN)
        {
            return (false, "Administrator accounts cannot be deleted.");
        }

        bool isPasswordValid = BCrypt.Net.BCrypt.Verify(password, user.PasswordHash);
        if (!isPasswordValid)
        {
            return (false, "Incorrect password. Account deletion aborted.");
        }

        _db.Users.Remove(user);
        await _db.SaveChangesAsync();

        return (true, "Account has been permanently deleted.");
    }
}

using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;
using UserService.Data;
using UserService.DTOs;
using UserService.Models;

namespace UserService.Services;

public interface IProfileService
{
    Task<UserProfileDto?> GetProfileByUserIdAsync(Guid userId);
    Task<(bool Success, string Message, UserProfileDto? Data)> UpdateProfileAsync(Guid userId, UpdateProfileDto dto);
    Task<(bool Success, string Message, string? ProfilePictureUrl)> UploadProfilePictureAsync(Guid userId, IFormFile? file, string webRootPath);
    Task<(bool Success, string Message)> RemoveProfilePictureAsync(Guid userId, string webRootPath);
}

public class ProfileService : IProfileService
{
    private readonly RescuePlateDbContext _db;
    private static readonly HashSet<string> AllowedExtensions = new(StringComparer.OrdinalIgnoreCase)
    {
        ".jpg", ".jpeg", ".png", ".webp"
    };

    private static readonly HashSet<string> AllowedMimeTypes = new(StringComparer.OrdinalIgnoreCase)
    {
        "image/jpeg", "image/png", "image/webp"
    };

    public ProfileService(RescuePlateDbContext db)
    {
        _db = db;
    }

    public async Task<UserProfileDto?> GetProfileByUserIdAsync(Guid userId)
    {
        var user = await _db.Users
            .Include(u => u.DonorProfile)
            .Include(u => u.OrganizationProfile)
            .FirstOrDefaultAsync(u => u.Id == userId);

        if (user == null) return null;

        var profile = new UserProfileDto
        {
            UserId = user.Id,
            Email = user.Email,
            Role = user.Role.ToString(),
            IsActive = user.IsActive,
            MemberSince = user.CreatedAt,
            ProfilePictureUrl = user.ProfilePictureUrl
        };

        if (user.Role == UserRole.DONOR && user.DonorProfile != null)
        {
            profile.BusinessOrOrgName = user.DonorProfile.BusinessName;
            profile.ContactName = user.DonorProfile.ContactPerson;
            profile.Phone = user.DonorProfile.Phone;
            profile.Address = user.DonorProfile.Address;
            profile.BioOrDescription = user.DonorProfile.Bio;
            profile.DonorType = user.DonorProfile.DonorType;
        }
        else if (user.Role == UserRole.ORGANIZATION && user.OrganizationProfile != null)
        {
            profile.BusinessOrOrgName = user.OrganizationProfile.OrganizationName;
            profile.ContactName = user.OrganizationProfile.ContactPerson;
            profile.Phone = user.OrganizationProfile.Phone;
            profile.Address = user.OrganizationProfile.Address;
            profile.BioOrDescription = user.OrganizationProfile.Description;
            profile.RegistrationNumber = user.OrganizationProfile.RegistrationNumber;
            profile.AcceptedFoodCategories = user.OrganizationProfile.AcceptedFoodCategories
                .Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList();
        }

        return profile;
    }

    public async Task<(bool Success, string Message, UserProfileDto? Data)> UpdateProfileAsync(Guid userId, UpdateProfileDto dto)
    {
        var user = await _db.Users
            .Include(u => u.DonorProfile)
            .Include(u => u.OrganizationProfile)
            .FirstOrDefaultAsync(u => u.Id == userId);

        if (user == null)
        {
            return (false, "User not found.", null);
        }

        if (user.Role == UserRole.DONOR)
        {
            if (user.DonorProfile == null)
            {
                user.DonorProfile = new DonorProfile { UserId = user.Id };
                _db.DonorProfiles.Add(user.DonorProfile);
            }

            if (!string.IsNullOrWhiteSpace(dto.BusinessOrOrgName)) user.DonorProfile.BusinessName = dto.BusinessOrOrgName.Trim();
            if (!string.IsNullOrWhiteSpace(dto.ContactName)) user.DonorProfile.ContactPerson = dto.ContactName.Trim();
            if (!string.IsNullOrWhiteSpace(dto.Phone)) user.DonorProfile.Phone = dto.Phone.Trim();
            if (!string.IsNullOrWhiteSpace(dto.Address)) user.DonorProfile.Address = dto.Address.Trim();
            if (dto.BioOrDescription != null) user.DonorProfile.Bio = dto.BioOrDescription.Trim();
            if (!string.IsNullOrWhiteSpace(dto.DonorType)) user.DonorProfile.DonorType = dto.DonorType.Trim();
            user.DonorProfile.UpdatedAt = DateTime.UtcNow;
        }
        else if (user.Role == UserRole.ORGANIZATION)
        {
            if (user.OrganizationProfile == null)
            {
                user.OrganizationProfile = new OrganizationProfile { UserId = user.Id };
                _db.OrganizationProfiles.Add(user.OrganizationProfile);
            }

            if (!string.IsNullOrWhiteSpace(dto.BusinessOrOrgName)) user.OrganizationProfile.OrganizationName = dto.BusinessOrOrgName.Trim();
            if (!string.IsNullOrWhiteSpace(dto.ContactName)) user.OrganizationProfile.ContactPerson = dto.ContactName.Trim();
            if (!string.IsNullOrWhiteSpace(dto.Phone)) user.OrganizationProfile.Phone = dto.Phone.Trim();
            if (!string.IsNullOrWhiteSpace(dto.Address)) user.OrganizationProfile.Address = dto.Address.Trim();
            if (dto.BioOrDescription != null) user.OrganizationProfile.Description = dto.BioOrDescription.Trim();
            if (dto.AcceptedFoodCategories != null)
            {
                user.OrganizationProfile.AcceptedFoodCategories = string.Join(";", dto.AcceptedFoodCategories);
            }
            user.OrganizationProfile.UpdatedAt = DateTime.UtcNow;
        }

        user.UpdatedAt = DateTime.UtcNow;
        await _db.SaveChangesAsync();

        var updatedProfile = await GetProfileByUserIdAsync(userId);
        return (true, "Profile updated successfully!", updatedProfile);
    }

    public async Task<(bool Success, string Message, string? ProfilePictureUrl)> UploadProfilePictureAsync(
        Guid userId, 
        IFormFile? file, 
        string webRootPath)
    {
        // 1. Scenario 5: Validate file presence & size
        if (file == null || file.Length == 0)
        {
            return (false, "Please select an image file to upload.", null);
        }

        const long maxSizeBytes = 5 * 1024 * 1024; // 5 MB
        if (file.Length > maxSizeBytes)
        {
            return (false, "Image file size exceeds the 5MB limit. Please choose a smaller image.", null);
        }

        // 2. Scenario 4: Validate extension & MIME type
        var extension = Path.GetExtension(file.FileName);
        if (string.IsNullOrEmpty(extension) || !AllowedExtensions.Contains(extension))
        {
            return (false, "Unsupported image format. Allowed formats are JPG, PNG, and WEBP.", null);
        }

        if (!AllowedMimeTypes.Contains(file.ContentType))
        {
            return (false, "Invalid image MIME type. Allowed formats are JPG, PNG, and WEBP.", null);
        }

        // 3. Scenario 5: Validate image binary magic bytes (prevent disguised malicious files)
        using (var stream = file.OpenReadStream())
        {
            if (!IsValidImageHeader(stream, extension))
            {
                return (false, "The uploaded file is not a valid or supported image.", null);
            }
        }

        // 4. Scenario 6: Find user in database
        var user = await _db.Users.FindAsync(userId);
        if (user == null)
        {
            return (false, "User account not found.", null);
        }

        // 5. Scenario 2: If user already has a profile picture, delete the old physical file
        if (!string.IsNullOrEmpty(user.ProfilePictureUrl))
        {
            DeletePhysicalFile(webRootPath, user.ProfilePictureUrl);
        }

        // 6. Save new physical file to wwwroot/uploads/profiles/
        var uploadsFolder = Path.Combine(webRootPath, "uploads", "profiles");
        if (!Directory.Exists(uploadsFolder))
        {
            Directory.CreateDirectory(uploadsFolder);
        }

        var uniqueFileName = $"profile_{userId}_{Guid.NewGuid():N}{extension.ToLowerInvariant()}";
        var filePath = Path.Combine(uploadsFolder, uniqueFileName);

        using (var outputStream = new FileStream(filePath, FileMode.Create))
        {
            await file.CopyToAsync(outputStream);
        }

        // 7. Update User ProfilePictureUrl in PostgreSQL
        var relativeUrl = $"/uploads/profiles/{uniqueFileName}";
        user.ProfilePictureUrl = relativeUrl;
        user.UpdatedAt = DateTime.UtcNow;

        await _db.SaveChangesAsync();

        return (true, "Profile picture updated successfully!", relativeUrl);
    }

    public async Task<(bool Success, string Message)> RemoveProfilePictureAsync(Guid userId, string webRootPath)
    {
        var user = await _db.Users.FindAsync(userId);
        if (user == null)
        {
            return (false, "User account not found.");
        }

        // Scenario 3: Delete physical file if exists and reset DB column
        if (!string.IsNullOrEmpty(user.ProfilePictureUrl))
        {
            DeletePhysicalFile(webRootPath, user.ProfilePictureUrl);
            user.ProfilePictureUrl = null;
            user.UpdatedAt = DateTime.UtcNow;
            await _db.SaveChangesAsync();
        }

        return (true, "Profile picture removed successfully.");
    }

    private static bool IsValidImageHeader(Stream stream, string extension)
    {
        try
        {
            stream.Position = 0;
            var header = new byte[12];
            var bytesRead = stream.Read(header, 0, header.Length);
            stream.Position = 0;

            if (bytesRead < 4) return false;

            var ext = extension.ToLowerInvariant();

            // JPEG magic bytes: FF D8 FF
            if (ext is ".jpg" or ".jpeg")
            {
                return header[0] == 0xFF && header[1] == 0xD8 && header[2] == 0xFF;
            }

            // PNG magic bytes: 89 50 4E 47 (0x89, 'P', 'N', 'G')
            if (ext is ".png")
            {
                return header[0] == 0x89 && header[1] == 0x50 && header[2] == 0x4E && header[3] == 0x47;
            }

            // WEBP magic bytes: RIFF (bytes 0..3) and WEBP (bytes 8..11)
            if (ext is ".webp")
            {
                return header[0] == (byte)'R' && header[1] == (byte)'I' && header[2] == (byte)'F' && header[3] == (byte)'F' &&
                       bytesRead >= 12 &&
                       header[8] == (byte)'W' && header[9] == (byte)'E' && header[10] == (byte)'B' && header[11] == (byte)'P';
            }

            return false;
        }
        catch
        {
            return false;
        }
    }

    private static void DeletePhysicalFile(string webRootPath, string relativeUrl)
    {
        try
        {
            var cleanPath = relativeUrl.TrimStart('/', '\\').Replace('/', Path.DirectorySeparatorChar);
            var fullPath = Path.Combine(webRootPath, cleanPath);
            if (File.Exists(fullPath))
            {
                File.Delete(fullPath);
            }
        }
        catch
        {
            // Ignore file deletion errors to prevent blocking DB operations
        }
    }
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.IdentityModel.Tokens;
using UserService.Models;

namespace UserService.Services;

public interface ITokenService
{
    string GenerateToken(User user, string businessOrOrgName, string contactName);
    string GeneratePreAuthChallengeToken(User user, int expiryMinutes = 5);
    string GenerateVerifiedAdminToken(User user, string businessOrOrgName, string contactName);
    ClaimsPrincipal? ValidateChallengeToken(string token);
}

public class TokenService : ITokenService
{
    private readonly IConfiguration _config;

    public TokenService(IConfiguration config)
    {
        _config = config;
    }

    public string GenerateToken(User user, string businessOrOrgName, string contactName)
    {
        var secretKey = _config["Jwt:SecretKey"] ?? "RescuePlate_Super_Secret_Key_For_Jwt_Authentication_2026_Sprint1_RescueFood";
        var issuer = _config["Jwt:Issuer"] ?? "RescuePlate.UserService";
        var audience = _config["Jwt:Audience"] ?? "RescuePlate.Client";

        var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey));
        var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, user.Id.ToString()),
            new(ClaimTypes.Email, user.Email),
            new(ClaimTypes.Role, user.Role.ToString()),
            new("BusinessName", businessOrOrgName),
            new("ContactName", contactName),
            new("IsActive", user.IsActive.ToString())
        };

        var token = new JwtSecurityToken(
            issuer: issuer,
            audience: audience,
            claims: claims,
            expires: DateTime.UtcNow.AddDays(7),
            signingCredentials: creds
        );

        return new JwtSecurityTokenHandler().WriteToken(token);
    }

    public string GeneratePreAuthChallengeToken(User user, int expiryMinutes = 5)
    {
        var secretKey = _config["Jwt:SecretKey"] ?? "RescuePlate_Super_Secret_Key_For_Jwt_Authentication_2026_Sprint1_RescueFood";
        var issuer = _config["Jwt:Issuer"] ?? "RescuePlate.UserService";
        var audience = _config["Jwt:Audience"] ?? "RescuePlate.Client";

        var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey));
        var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, user.Id.ToString()),
            new(ClaimTypes.Email, user.Email),
            new(ClaimTypes.Role, user.Role.ToString()),
            new("purpose", "admin_access_key_challenge")
        };

        var token = new JwtSecurityToken(
            issuer: issuer,
            audience: audience,
            claims: claims,
            expires: DateTime.UtcNow.AddMinutes(expiryMinutes),
            signingCredentials: creds
        );

        return new JwtSecurityTokenHandler().WriteToken(token);
    }

    public string GenerateVerifiedAdminToken(User user, string businessOrOrgName, string contactName)
    {
        var secretKey = _config["Jwt:SecretKey"] ?? "RescuePlate_Super_Secret_Key_For_Jwt_Authentication_2026_Sprint1_RescueFood";
        var issuer = _config["Jwt:Issuer"] ?? "RescuePlate.UserService";
        var audience = _config["Jwt:Audience"] ?? "RescuePlate.Client";

        var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey));
        var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

        var claims = new List<Claim>
        {
            new(ClaimTypes.NameIdentifier, user.Id.ToString()),
            new(ClaimTypes.Email, user.Email),
            new(ClaimTypes.Role, UserRole.ADMIN.ToString()),
            new("admin_verified", "true"),
            new("BusinessName", string.IsNullOrWhiteSpace(businessOrOrgName) ? "RescuePlate System Admin" : businessOrOrgName),
            new("ContactName", string.IsNullOrWhiteSpace(contactName) ? "System Administrator" : contactName),
            new("IsActive", user.IsActive.ToString())
        };

        var token = new JwtSecurityToken(
            issuer: issuer,
            audience: audience,
            claims: claims,
            expires: DateTime.UtcNow.AddDays(7),
            signingCredentials: creds
        );

        return new JwtSecurityTokenHandler().WriteToken(token);
    }

    public ClaimsPrincipal? ValidateChallengeToken(string token)
    {
        var secretKey = _config["Jwt:SecretKey"] ?? "RescuePlate_Super_Secret_Key_For_Jwt_Authentication_2026_Sprint1_RescueFood";
        var issuer = _config["Jwt:Issuer"] ?? "RescuePlate.UserService";
        var audience = _config["Jwt:Audience"] ?? "RescuePlate.Client";

        var tokenHandler = new JwtSecurityTokenHandler();
        var validationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,
            ValidIssuer = issuer,
            ValidAudience = audience,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),
            ClockSkew = TimeSpan.Zero
        };

        try
        {
            var principal = tokenHandler.ValidateToken(token, validationParameters, out _);
            var purposeClaim = principal.FindFirst("purpose")?.Value;
            if (purposeClaim != "admin_access_key_challenge")
            {
                return null;
            }
            return principal;
        }
        catch
        {
            return null;
        }
    }
}

