    public async Task VerifyAccessKeyAsync_5FailedAttempts_LocksOutAccountAndIP()
    {
        // Arrange (A5)
        var adminUser = new User
        {
            Id = Guid.NewGuid(),
            Email = "target_admin@rescueplate.org",
